/usr/bin/zsh -lc "cd /var/tmp/loop-bench/runs/0dd1ace019d4/workspace/target && cat > scripts/lore-descriptor.mjs <<'EOF'
export function testDescriptor(file, assertion, source) {
  const preceding = source.split(/\\r?\\n/).slice(0, assertion.location?.line - 1);
  const stamp = preceding.reverse().find(line => line.trim());
  const spec = /"'^'"\\s*\\/\\/ @spec (specs\\/\\S+#\\d+)\\s*"'$/.exec(stamp ?? '"'')?.[1];
  return {
    id: "'`${file}::${assertion.fullName}`,
    name: assertion.fullName,
    file,
    ...(spec ? {spec} : {}),
  };
}
EOF
 timeout 300 npm test -- --runTestsByPath scripts/lore-descriptor.test.ts --runInBand'
